test('PUT /blobs/{key} returns 400, not 500, when the key cannot be written to disk', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  // A single path segment this long is rejected by the filesystem
  // (ENAMETOOLONG) even though it passes all of resolveBlobPath's structural
  // checks (no traversal, no NUL, valid UTF-8). This stands in for the wider
  // class of keys that pass structural validation but fail at the actual
  // write/rename step for OS-level reasons - the fix must catch that class
  // generically, not this specific error code.
  const key = 'a'.repeat(300);
  const res = await request(port, 'PUT', `/blobs/${key}`, Buffer.from('x'));

  assert.equal(res.status, 400);
  assert.deepEqual(fs.readdirSync(dataDir), []);

  const health = await get(port, '/healthz');
  assert.equal(health.status, 200);
});

test('PUT /blobs/{key} does not leave a temp file behind when the write fails', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  const key = 'b'.repeat(300);
  await request(port, 'PUT', `/blobs/${key}`, Buffer.from('x'));

  assert.deepEqual(fs.readdirSync(dataDir), []);
});

test('PUT /blobs/{key} with unusual decoded bytes (C1 control, supplementary plane, high Latin-1) never returns 500', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  // The reported symptom: key decodes (via percent-encoding) to bytes that
  // are structurally valid (well-formed UTF-8, no traversal/NUL/surrogate
  // issues) but historically triggered an uncaught OS-level error during the
  // write itself. The contract allows only 201 or 400 here - never 500 -
